1	#!/usr/bin/env bun
2	/**
3	 * stop_on_close.ts — closing an issue an agent is working on asks that run to stop.
4	 *
5	 * ## Why closing has to mean something
6	 *
7	 * It already looked like it did. #803 was closed by hand while its run held the
8	 * in-progress label; the run kept going for five more minutes, opened a pull request,
9	 * and nothing anywhere said that closing had not stopped it. A gesture that reads as
10	 * "stop this" and does nothing is worse than no gesture, because the person walks
11	 * away believing it worked.
12	 *
13	 * ## Why a stop rather than a reopen
14	 *
15	 * Reopening would undo a decision a person just made, and the comment guard's reason
16	 * for deleting does not apply here: that guard prevents a second run from racing the
17	 * first, and closing starts no run. So the issue stays closed and the work stops —
18	 * which is what closing appeared to mean all along.
19	 *
20	 * ## Why only a person's close
21	 *
22	 * An agent closing the issue it is working on is a normal path, not an accident:
23	 * `domain/machinery/atomaton-data-pruning.ts` is built around it ("the agent closes it and the
24	 * job continues"). Stopping the run that just closed its own issue would cut it off
25	 * mid-wrap-up, so the caller passes the closer and a bot closer is no-op'd here.
26	 *
27	 * ## The mechanism is the existing one
28	 *
29	 * `/stop` is a comment carrying `STOP_TAG`, which the running job polls for — it has
30	 * to be a comment because nothing outside a job can reach into it. That works just as
31	 * well from an `issues: closed` workflow, so no second stop path exists.
32	 *
33	 * Usage:
34	 *   stop_on_close.ts --number N --closer LOGIN [--closer-type Bot|User]
35	 */
36	import { parseArgs } from "node:util";
37	import { LLM_CONTEXT_TAG, STOP_TAG } from "../../adapters/github/tags.ts";
38	import { isHumanActor } from "../../domain/work/actor.ts";
39	import { closedTheTreeNotice, stopOnCloseNotice } from "../../domain/work/closed-target.ts";
40	import { descendants, nodesToClose, nodesToStop, subtree } from "../../domain/work/work-tree.ts";
41	import { closeSubtreeUnder, readWorkTree } from "../../adapters/github/work-tree.ts";
42	import { defineScript } from "./lib/script-ref.ts";
43	
44	export interface StopOnCloseArgs {
45	  number: string | number;
46	  closer: string;
47	  "closer-type": string;
48	}
49	
50	export const ref = defineScript<StopOnCloseArgs>(import.meta.url);
51	
52	/**
53	 * The whole comment, tags included.
54	 *
55	 * `STOP_TAG` is what the running job reads; `LLM_CONTEXT_TAG` keeps this out of the
56	 * session, for the same reason `/stop`'s own notice is excluded — it is addressed to
57	 * a person, and an agent reading it would take it as something it was told.
58	 */
59	export function stopOnCloseBody(
60	  number: number,
61	  closed: readonly number[],
62	  stopped: readonly number[],
63	): string {
64	  return [
65	    LLM_CONTEXT_TAG.write("exclude"),
66	    STOP_TAG.write("requested"),
67	    stopOnCloseNotice(number),
68	    closedTheTreeNotice(closed, stopped),
69	  ].join("\n");
70	}
71	
72	function main(): void {
73	  const { values } = parseArgs({
74	    args: Bun.argv.slice(2),
75	    options: {
76	      number: { type: "string" },
77	      closer: { type: "string" },
78	      "closer-type": { type: "string" },
79	    },
80	  });
81	
82	  if (!values.number) {
83	    console.error("usage: stop_on_close.ts --number N --closer LOGIN [--closer-type Bot|User]");
84	    process.exit(2);
85	  }
86	
87	  const repo = process.env.GITHUB_REPOSITORY ?? "";
88	  const number = String(values.number);
89	  const closer = (values.closer ?? "").trim();
90	
91	  if (!isHumanActor(values["closer-type"])) {
92	    console.error(`#${number} was closed by a bot, which is how an agent finishes its own work. Nothing to stop.`);
93	    return;
94	  }
95	
96	  // Closing ends a line of work rather than one node, so the sub-issues and pull
97	  // requests under it go with it. See `domain/work/work-tree.ts`.
98	  //
99	  // The tree is read before anything is decided, and that ordering is the fix for what
100	  // this used to do: it read the root's label, found none, and returned — which is
101	  // right about the root and wrong about the work, because an issue can be closed with
102	  // nothing running on it and a live chain underneath.
103	  const root = Number(number);
104	  const { nodes, problems: readProblems } = readWorkTree(repo, root);
105	  // A failed read is not "nothing to do". The answer this could not determine must not
106	  // be the one that stays quiet — the rule `guard_comment_during_run.ts` follows, for
107	  // the same reason.
108	  if (nodes.length === 0) {
109	    console.error(`::error::Could not read the work under #${root}: ${readProblems.join("; ")}`);
110	    process.exit(1);
111	  }
112	
113	  const all = subtree(nodes, root);
114	  const under = descendants(all, root);
115	  const toStop = nodesToStop(all);
116	  const toClose = nodesToClose(under);
117	  if (toStop.length === 0 && toClose.length === 0) {
118	    console.error(`Nothing is running under #${root} and nothing under it is open. Nothing to do.`);
119	    return;
120	  }
121	
122	  const result = closeSubtreeUnder(
123	    repo,
124	    root,
125	    stopOnCloseBody(root, toClose.map((n) => n.number), nodesToStop(under).map((n) => n.number)),
126	  );
127	  result.problems.push(...readProblems);
128	
129	  for (const problem of result.problems) console.error(`::warning::${problem}`);
130	  // Fatal only when the root got nothing. That comment IS the stop: without it the run
131	  // polls, finds nothing, and keeps going — while the person who closed the issue has
132	  // every reason to believe it is winding down.
133	  if (!result.rootNotified) process.exit(1);
134	
135	  console.error(
136	    `#${root} was closed by ${closer || "(unknown)"}. ` +
137	      `Stopped: ${result.stopped.map((n) => `#${n}`).join(", ") || "none"}. ` +
138	      `Closed under it: ${result.closed.map((n) => `#${n}`).join(", ") || "none"}.`,
139	  );
140	}
141	
142	if (import.meta.main) main();

