1	/**
2	 * work-tree.ts — read the work tree out of GitHub, so `domain/work/work-tree.ts` can do
3	 * arithmetic on it.
4	 *
5	 * ## Why a walk rather than one query
6	 *
7	 * There is no single query for "everything under #803", so the tree is found by
8	 * descending one level at a time. The trees this builds are shallow — an issue, its
9	 * sub-issues, their pull requests.
10	 *
11	 * ## One source per kind of edge, and why they differ
12	 *
13	 * A sub-issue comes from GitHub's own link, which is the only record of that edge —
14	 * `create_sub_issue` fails rather than leave one unmade. It also covers what no agent
15	 * made: an issue a person opened, decomposed with the sub-issue control and closed is
16	 * a tree this would otherwise see as a single node, and closing it would leave its
17	 * children open. That argument is `issue-links.ts`'s.
18	 *
19	 * A pull request comes from its `atomaton:parent-issue` tag, because GitHub's own
20	 * PR-to-issue link does not survive here: GitHub drops that link once anything but
21	 * the pull request's own merge closes the issue, and this design does that twice —
22	 * a sub-issue's pull request merges into its PARENT's branch, so the auto-close
23	 * never fires, and the post-merge agent closes the sub-issue itself. The count that
24	 * measured the drop is `adapters/github/tags.ts`'s.
25	 *
26	 * ## The pull request search is a prefilter, never the answer
27	 *
28	 * GitHub tokenizes, so a query for `atomaton:parent-issue=5` also returns the pull
29	 * requests of #50. Every result is checked against the tag reader before it is
30	 * believed — the same trap `aggregate_sub_issues.ts` used to document, and the reason
31	 * it re-read the body it had just searched on.
32	 *
33	 * ## What a failed read means here
34	 *
35	 * A subtree that could not be read in full is reported as such rather than returned
36	 * short. The callers act on what they are given — a stop posts to every node, a close
37	 * closes every node — and a partial tree silently treated as whole is a close that
38	 * leaves work running with nobody told.
39	 */
40	import { gh, ghRead } from "./gh.ts";
41	import { issueLinks } from "./issue-links.ts";
42	import { commentBodies, runInFlight } from "./thread.ts";
43	import { issueOutcome, pullRequestOutcome, saysOpen } from "./outcome.ts";
44	import { ENDED_TAG, LLM_CONTEXT_TAG, PARENT_ISSUE_TAG, STOP_TAG, isQuotation } from "./tags.ts";
45	import {
46	  closeReachedNotice,
47	  descendants,
48	  MAX_DEPTH,
49	  nodesToClose,
50	  nodesToStop,
51	  stopReachedNotice,
52	  subtree,
53	  type NodeState,
54	  type WorkNode,
55	} from "../../domain/work/work-tree.ts";
