57	interface Listed {
58	  number: number;
59	  body?: string;
60	  state?: string;
61	  labels?: ({ name?: string } | string)[];
62	}
63	
64	/**
65	 * The listing, or null when it could not be read as one.
66	 *
67	 * Null rather than `[]`, because the two answers travel to the same place and mean
68	 * opposite things. `[]` is "this parent has no children of that kind"; an unreadable
69	 * listing is "nobody knows", and a stop that walks a tree built from the second
70	 * reaches whatever it happened to see and reports success.
71	 *
72	 * The failed CALL was already reported. This is the narrower case — `gh` exited zero
73	 * and handed back something that is not JSON — and it was the one that answered
74	 * "none".
75	 */
76	function parseListed(stdout: string): Listed[] | null {
77	  try {
78	    return JSON.parse(stdout || "[]") as Listed[];
79	  } catch {
80	    return null;
81	  }
82	}
83	
84	/**
85	 * Whether a run is in flight on a node, from its thread.
86	 *
87	 * The `atomaton/in-progress` label used to answer this, and it is a cache written
88	 * late: the runner sets it after the job starts and clears it when the job ends, so a
89	 * run that died leaves it set and a run that has been asked for but not yet started
90	 * has none. The thread is the answer itself -- see `runInFlight`.
91	 *
92	 * A read that fails is a problem, not "nothing is running": a stop that read a failed
93	 * read as idle would leave a live run going, and a resume would start a second one.
94	 */
95	function runningOn(repo: string, number: number): { running: boolean; problem?: string } {
96	  try {
97	    return { running: runInFlight(repo, number) };
98	  } catch (e) {
99	    return { running: false, problem: `could not read the thread on #${number}: ${(e as Error).message}` };
100	  }
101	}
102	
103	/** One node, read through the endpoint that answers for an issue and a pull request alike. */
104	function readNode(repo: string, number: number): { node?: WorkNode; problem?: string } {
105	  const { code, stdout, stderr } = ghRead("api", `repos/${repo}/issues/${number}`);
106	  if (code !== 0) {
107	    return { problem: `could not read #${number}: ${(stderr || stdout).trim().split("\n")[0] ?? ""}` };
108	  }
109	  let raw: {
110	    state?: string;
111	    state_reason?: string | null;
112	    body?: string;
113	    labels?: { name?: string }[];
114	    pull_request?: { merged_at?: string | null };
115	  };
116	  try {
117	    raw = JSON.parse(stdout) as typeof raw;
118	  } catch {
119	    return { problem: `the response for #${number} was not JSON` };
120	  }
121	
122	  const isPr = raw.pull_request !== undefined;
123	  if (raw.state !== "open" && raw.state !== "closed") {
124	    return { problem: `#${number} reported an unrecognised state ${JSON.stringify(raw.state ?? null)}` };
125	  }
126	  const state: NodeState =
127	    raw.state === "open"
128	      ? "open"
129	      : isPr
130	        ? pullRequestOutcome(Boolean(raw.pull_request?.merged_at))
131	        : issueOutcome(raw.state_reason);
132	
133	  const { running, problem } = runningOn(repo, number);
134	  if (problem) return { problem };
135	
136	  return {
137	    node: {
138	      number,
139	      kind: isPr ? "pull-request" : "issue",
140	      state,
141	      // A pull request's parent is its `atomaton:parent-issue` tag; an issue's is
142	      // GitHub's own sub-issue link, read by the caller that walks downward. This
143	      // used to be `PARENT_TAG.read(body) ?? PARENT_ISSUE_TAG.read(body)` — two
144	      // spellings tried in turn, three lines after `isPr` had already settled which
145	      // one this is, so an issue carrying a pull request's tag was accepted without
146	      // a word. The body is GitHub's, so the tag is read out of its prose: a sample
147	      // of the tag in a fenced block is not a parent (#304).
148	      parent: isPr ? PARENT_ISSUE_TAG.readProse(raw.body ?? "") : undefined,
149	      running,
150	    },
151	  };
152	}
153	
154	/**
155	 * The issues filed under `parent`, and the pull requests opened for it.
156	 *
157	 * The issues come from GitHub's own sub-issue links, through `issueLinks`, which is
158	 * the single record of that edge — see `adapters/github/parent-issue.ts`. There used to be a
159	 * search for `atomaton:parent=N in:body` beside it and a union afterwards, because
