172	function readChildren(repo: string, parent: number): { nodes: WorkNode[]; problems: string[] } {
173	  const nodes: WorkNode[] = [];
174	  const problems: string[] = [];
175	
176	  const prs = ghRead(
177	    "pr", "list", "--repo", repo, "--state", "all", "--limit", "200",
178	    "--search", `${PARENT_ISSUE_TAG.search(parent)} in:body`,
179	    "--json", "number,body,state,labels",
180	  );
181	  if (prs.code !== 0) problems.push(`could not list the pull requests for #${parent}`);
182	  const listedPrs = parseListed(prs.stdout);
183	  if (listedPrs === null) problems.push(`the pull request listing for #${parent} was not readable`);
184	  for (const found of listedPrs ?? []) {
185	    // `proseOnly` here is also what keeps the search above honest: search matches the
186	    // tag text inside a fence too, and the read is the confirmation that a listed body
187	    // actually carries the link (#304).
188	    if (PARENT_ISSUE_TAG.readProse(found.body ?? "") !== parent) continue;
189	    const { running, problem } = runningOn(repo, found.number);
190	    if (problem) {
191	      problems.push(problem);
192	      continue;
193	    }
194	    nodes.push({
195	      number: found.number,
196	      kind: "pull-request",
197	      // `gh` says outright whether it merged, so the outcome needs nothing else.
198	      state: saysOpen(found.state) ? "open" : pullRequestOutcome(found.state === "MERGED"),
199	      parent,
200	      running,
201	    });
202	  }
203	
204	  // The sub-issues, and the pull requests GitHub itself knows about. `issueLinks`'s
205	  // docstring is the argument for asking it: "the relationships have to survive an
206	  // issue a person opened, decomposed and closed without an agent ever touching it,
207	  // and markers only exist where an agent has been."
208	  //
209	  // A pull request GitHub knows about and the tag search above missed still does —
210	  // rare by construction, since it is one no agent opened.
211	  const links = issueLinks(repo, parent);
212	  if (links.unavailable) {
213	    problems.push(`could not read GitHub's own links for #${parent}: ${links.unavailable}`);
214	  }
215	  const already = new Set(nodes.map((node) => node.number));
